import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Regolare la luminosità richiede solo pochi minuti. Carichi la foto, trascini un cursore, controlli il risultato e scarichi la versione più chiara.</p>\n<p>Questa guida pratica ti accompagna in tutto il procedimento, passo passo. Copre il cursore, i preset rapidi, le modalità di confronto e le impostazioni di esportazione che mantengono il risultato naturale.</p>\n<p>Alla fine saprai sistemare un ritratto scuro, un paesaggio spento o uno screenshot torbido su qualsiasi dispositivo. Conserva la foto originale finché non hai controllato il risultato.</p>\n<h2 id=\"before-you-start\">Prima di iniziare: valuta quanto è scura</h2>\n<p>Guarda la foto prima di aprire lo strumento. È leggermente scura, molto scura o scura solo in una zona? La risposta ti dice quanta luminosità le serve.</p>\n<p>Una foto leggermente scura ha bisogno del 10-15%. Una molto scura può aver bisogno del 30% o più, ma spostamenti grandi rischiano di bruciare le luci.</p>\n<p>Controlla se la foto è anche piatta o spenta. Una foto scura e piatta ha bisogno di luminosità e contrasto insieme, quindi preparati a entrambe le modifiche, non solo a una.</p>\n<p>Apri lo strumento <a href=\"/it/regola-luminosita-immagine/\">Regola luminosità immagine</a> nel browser. Tutto funziona in locale, quindi la tua foto non viene mai caricata su un server.</p>\n<h2 id=\"step-by-step\">Regola la luminosità in cinque passaggi</h2>\n<p>Il procedimento è lo stesso per una foto, uno screenshot o un documento scansionato. Carica, regola, confronta, esporta e verifica il file scaricato.</p>\n<p>Prenditi il tempo necessario per il cursore. Piccoli spostamenti fanno una grande differenza, e l’anteprima ti mostra esattamente quando la foto sembra giusta.</p>\n<ol>\n<li>Carica l’immagine trascinandola nella zona di caricamento, scegliendola dal dispositivo oppure incollando uno screenshot con Ctrl+V.</li>\n<li>Trascina il cursore Livello di luminosità a destra per schiarire o a sinistra per scurire, guardando l’anteprima in tempo reale.</li>\n<li>Prova un preset rapido per un test in un clic, poi rifinisci con il cursore se il risultato è vicino ma non del tutto giusto.</li>\n<li>Usa le modalità Dopo, Prima, Confronto diviso o Confronto a schermo intero per controllare il risultato rispetto all’originale.</li>\n<li>Scegli il formato di esportazione e la qualità, poi clicca Scarica per salvare l’immagine modificata.</li>\n</ol>\n<p>Apri il file scaricato una volta prima di usarlo. Conferma che la foto sembri illuminata in modo naturale e che nessuna zona chiara sia diventata bianca.</p>\n<h2 id=\"using-the-slider\">Usare il cursore della luminosità</h2>\n<p>Il cursore va da valori negativi a valori positivi, con lo zero che significa nessun cambiamento. Spostandolo a destra si schiarisce l’immagine, spostandolo a sinistra la si scurisce.</p>\n<p>Trascina lentamente e guarda l’anteprima. L’aggiornamento in tempo reale mostra esattamente come risponde l’immagine, così puoi fermarti nel punto in cui la foto sembra giusta.</p>\n<p>I piccoli spostamenti sono meglio di quelli grandi. Una variazione del 10-15% basta spesso, e spostamenti più grandi bruciano in fretta le luci.</p>\n<p>Lo strumento mostra la tua foto a +15% subito dopo il caricamento. Questo punto di partenza ti dà subito un’idea di come appare uno schiarimento moderato.</p>\n<h2 id=\"using-quick-presets\">Usare i preset rapidi</h2>\n<p>Lo strumento include preset rapidi che applicano valori comuni di luminosità in un solo clic. Sono un modo veloce per provare livelli diversi senza trascinare il cursore.</p>\n<p>Clicca un preset e guarda l’anteprima. Se il risultato è vicino ma non del tutto giusto, rifinisci con il cursore da quel punto.</p>\n<p>Usa i preset per confrontare le opzioni in fretta. Un preset a +15% accanto a uno a +30% ti mostra quanta luminosità la foto può sopportare.</p>\n<p>Per una serie di foto simili, lo stesso preset mantiene coerenti i risultati. Una serie di scatti scuri in interni, tutti schiariti dello stesso valore, sembra una serie vera.</p>\n<h2 id=\"using-compare-modes\">Usare le modalità di confronto</h2>\n<p>Le modalità di confronto mostrano l’originale e la versione modificata insieme. La vista Dopo mostra l’immagine schiarita, la vista Prima mostra l’originale.</p>\n<p>Il Confronto diviso è il più utile per lavorare sulla luminosità. Mostra entrambe le versioni affiancate, con una linea netta tra loro, così vedi esattamente che cosa è cambiato.</p>\n<p>Il Confronto a schermo intero ti dà la vista più grande. È il modo migliore per giudicare una foto schiarita, perché l’immagine a dimensione intera mostra dettagli che una piccola anteprima nasconde.</p>\n<p>Controlla la vista di confronto prima di ogni download. Un’occhiata veloce rileva uno schiarimento eccessivo che una piccola anteprima potrebbe nascondere.</p>\n<h2 id=\"brightening-a-dark-photo\">Schiarire una foto scura</h2>\n<p>Carica la foto scura e trascina il cursore a +15%. Controlla l’anteprima: il soggetto dovrebbe essere chiaramente visibile e le zone chiare dovrebbero mostrare ancora i dettagli.</p>\n<p>Se la foto è ancora troppo scura, aumenta il cursore a piccoli passi del 5%. Ogni passo aggiunge un po’ di luce in più, e l’anteprima mostra quando fermarsi.</p>\n<p>Guarda le luci mentre procedi. La fronte, il cielo e qualsiasi superficie bianca bruciano per prime, e una foto con macchie bianche sembra peggiore di una scura.</p>\n<p>Se dopo lo schiarimento la foto sembra piatta, aggiungi contrasto. Apri lo strumento <a href=\"/it/regola-contrasto-immagine/\">Regola contrasto immagine</a> e applica una piccola spinta per ripristinare la profondità.</p>\n<h2 id=\"darkening-a-bright-photo\">Scurire una foto troppo chiara</h2>\n<p>Trascina il cursore a sinistra per una foto troppo chiara. Valori negativi come −15% o −30% approfondiscono le ombre e ripristinano la ricchezza.</p>\n<p>Controlla le ombre mentre scurisci. Dovrebbero guadagnare profondità senza trasformarsi in macchie nere senza alcun dettaglio.</p>\n<p>Scurire aiuta anche quando una foto dovrà stare dietro a un testo. Un’immagine scurita rende leggibile il testo bianco, e va bene per slide, poster e grafiche social.</p>\n<p>Per una foto troppo chiara nel cielo e troppo scura nel primo piano, accetta un compromesso. La luminosità sposta tutto insieme, quindi nessuna direzione da sola sistemerà entrambe le zone.</p>\n<h2 id=\"fixing-a-screenshot\">Sistemare uno screenshot scuro</h2>\n<p>Incolla uno screenshot direttamente con Ctrl+V per saltare il passaggio del salvataggio. L’immagine compare subito nell’editor, pronta da schiarire.</p>\n<p>Aumenta la luminosità finché il testo è chiaro e lo sfondo è bianco. Un documento con uno sfondo bianco pulito e il testo scuro è facile da leggere e da stampare.</p>\n<p>Fai attenzione al rumore nelle zone scure. Uno screenshot molto schiarito può mostrare deboli motivi a blocchi, soprattutto in un JPEG già compresso.</p>\n<p>Esporta gli screenshot in PNG. Il formato senza perdite mantiene nitido il testo piccolo, e questo conta quando lo screenshot mostra un’impostazione o un messaggio di errore.</p>\n<h2 id=\"previewing\">Controllare l’anteprima prima di scaricare</h2>\n<p>Controlla sempre l’anteprima prima di scaricare. Verifica che la foto sembri illuminata in modo naturale, che nessuna zona chiara sia diventata bianca e che il soggetto sia chiaramente visibile.</p>\n<p>Usa la vista di confronto diviso per controllare la modifica. Mostra l’originale e la versione modificata affiancate, così vedi esattamente che cosa ha fatto la luminosità.</p>\n<p>Ingrandisci le zone chiare a dimensione intera. Un cielo o una fronte che in una piccola anteprima sembra a posto può risultare bruciato se visto in grande.</p>\n<p>Se il risultato sembra slavato, abbassa il cursore del 5% e controlla di nuovo. Piccole riduzioni spesso ripristinano i dettagli senza rendere di nuovo scura la foto.</p>\n<h2 id=\"choosing-export-format\">Scegliere il formato di esportazione</h2>\n<p>Scegli il JPG per le foto che vuoi condividere. Mantiene piccoli i file e funziona ovunque, e un’impostazione di alta qualità mantiene pulita la foto schiarita.</p>\n<p>Scegli il PNG per screenshot e grafiche con testo. Il PNG è senza perdite, quindi i bordi delle lettere restano nitidi, e conserva la trasparenza quando serve.</p>\n<p>Scegli il WebP quando vuoi file piccoli con una buona qualità. Funziona bene per le immagini web, anche se alcuni sistemi più vecchi rifiutano ancora questo formato.</p>\n<p>Ricorda che il cursore della qualità si nasconde per il PNG, perché il PNG è senza perdite e non ha un’impostazione di qualità da regolare. È un comportamento normale, non un problema dello strumento.</p>\n<h2 id=\"adjusting-on-mobile\">Regolare la luminosità da telefono o tablet</h2>\n<p>Lo strumento funziona sui touchscreen, quindi puoi sistemare una foto scura direttamente dal telefono che l’ha scattata. Caricala dalla galleria, trascina il cursore con il dito e scarica il risultato.</p>\n<p>Trascinare un cursore con il dito è meno preciso che con il mouse. Usa i preset rapidi per valori esatti, poi rifinisci con piccoli trascinamenti.</p>\n<p>Controlla l’anteprima a dimensione intera prima di scaricare. Una modifica di luminosità che sullo schermo piccolo del telefono sembra buona può risultare troppo forte se vista da un computer.</p>\n<p>I file scaricati finiscono nella solita cartella dei download. Da lì puoi condividere la foto schiarita direttamente in un’app di chat, in un’email o in un post social.</p>\n<h2 id=\"troubleshooting\">Risolvere i problemi più comuni della luminosità</h2>\n<p>Se la foto sembra slavata, il cursore è troppo alto. Abbassalo a piccoli passi finché le luci mostrano di nuovo i dettagli, poi controlla le ombre.</p>\n<p>Se dopo lo schiarimento la foto è ancora scura, l’originale potrebbe essere troppo scuro per essere salvato. Una foto quasi nera non si può sistemare con la sola luminosità, e rifare lo scatto è la scelta migliore.</p>\n<p>Se compare rumore nelle ombre, lo schiarimento è troppo forte per la fonte. Abbassa il cursore e accetta una foto leggermente più scura, oppure parti da un originale migliore.</p>\n<p>Se l’anteprima sembra diversa dal file scaricato, controlla il formato di esportazione e la qualità. Un’impostazione di bassa qualità JPG può ammorbidire l’intera immagine, comprese le zone chiare.</p>\n<h2 id=\"brightness-plus-contrast\">Luminosità più contrasto: la coppia più comune</h2>\n<p>Una foto scura e piatta ha bisogno di luminosità e contrasto insieme. Schiarisci prima per alzare il livello generale, poi aggiungi contrasto per ripristinare la profondità.</p>\n<p>Usa lo strumento <a href=\"/it/regola-contrasto-immagine/\">Regola contrasto immagine</a> dopo aver schiarito, quando l’immagine sembra grigia e senza vita. Una piccola spinta di contrasto riporta ombre e luci.</p>\n<p>Fai i passaggi in ordine: prima la luminosità, poi il contrasto. Invertirli può rendere più difficile giudicare la regolazione del contrasto, perché l’immagine è ancora scura.</p>\n<p>Controlla la vista di confronto dopo ogni passaggio. La vista divisa mostra esattamente che cosa ha fatto ogni regolazione, così puoi fermarti quando la foto sembra giusta.</p>\n<h2 id=\"saving-settings\">Salvare le impostazioni per la prossima volta</h2>\n<p>Annota il valore di luminosità che ha funzionato per una serie di foto simili. Una breve nota, per esempio «foto in interni +20%», ti evita di indovinare la prossima volta.</p>\n<p>Per una serie di foto scattate con la stessa luce, usa lo stesso valore per tutte. Una luminosità coerente in una serie sembra professionale, mentre valori misti sembrano casuali.</p>\n<p>Conserva i file originali. Un valore di luminosità che va bene per una foto potrebbe non andare bene per un’altra, e l’originale ti permette di provare un altro livello senza danni aggiuntivi.</p>\n<p>Rileggi le tue note ogni tanto. Man mano che la tua fotocamera e la tua illuminazione migliorano, i valori di luminosità di cui hai bisogno cambieranno, e le vecchie note possono trarti in inganno.</p>\n<h2 id=\"quick-tips\">Consigli rapidi per una luminosità migliore</h2>\n<p>Schiarisci a piccoli passi. Una variazione del 5% alla volta ti dà controllo, mentre un salto grande può superare il valore giusto prima che tu te ne accorga.</p>\n<p>Controlla le luci, non solo le ombre. Una foto è troppo schiarita quando le zone chiare perdono i dettagli, anche se le zone scure sembrano buone.</p>\n<p>Usa la vista di confronto ogni volta. Un’occhiata veloce all’originale accanto alla modifica rileva errori che una piccola anteprima nasconde.</p>\n<p>Salva la foto originale senza modifiche. Una volta che una modifica di luminosità è stata fissata in un’esportazione, non si può più annullare da quel file.</p>\n<h2 id=\"brightening-for-presentation\">Schiarire una foto per una presentazione</h2>\n<p>Una foto usata in una slide deve essere abbastanza chiara da vedersi dal fondo della sala. Un’immagine scura su uno schermo grande sembra torbida, mentre una ben illuminata si legge chiaramente.</p>\n<p>Schiarisci le foto per le slide un po’ più di quanto faresti per un feed. I proiettori attenuano i colori e riducono la luminosità, quindi una foto che sul laptop sembra a posto può sembrare scura quando viene proiettata.</p>\n<p>Controlla la foto sul proiettore vero, se puoi. Una slide di prova mostra se la luminosità regge nella stanza, dove la luce è molto diversa da quella della tua scrivania.</p>\n<p>Mantieni lo schiarimento uniforme in tutta la slide. Una foto chiara in un angolo e scura in un altro distrae il pubblico dalle parole sopra di essa.</p>\n<h2 id=\"brightening-old-scans\">Schiarire vecchie foto scansionate</h2>\n<p>Le vecchie foto scansionate sono spesso scure e sbiadite. L’età attenua la stampa, lo scanner legge male i toni e il risultato è un’immagine grigia e torbida che ha bisogno di una spinta.</p>\n<p>Aumenta la luminosità a piccoli passi e guarda i visi. L’obiettivo è una foto che sembri la stampa originale quando era nuova, non una sua versione slavata.</p>\n<p>Le vecchie scansioni hanno spesso bisogno di contrasto oltre che di luminosità. La stampa sbiadita ha poca gamma tonale, quindi uno schiarimento più una piccola spinta di contrasto ripristina la profondità.</p>\n<p>Lavora dalla migliore scansione che hai. Una scansione ad alta risoluzione si schiarisce molto meglio di una a bassa risoluzione, perché c’è più dettaglio da far emergere per la modifica.</p>\n<p>Per il confronto, leggi <a href=\"/it/blog/luminosita-esposizione-contrasto-differenze/\">Luminosità, esposizione e contrasto: le basi del fotoritocco</a>. Per la panoramica completa, leggi <a href=\"/it/blog/come-regolare-luminosita-immagine-guida-completa/\">Regolare la luminosità di un’immagine: guida completa</a>. Per sistemare il contrasto piatto dopo lo schiarimento, prova lo strumento <a href=\"/it/regola-contrasto-immagine/\">Regola contrasto immagine</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Come schiarisco una foto dal telefono?","answer":"Apri lo strumento Regola luminosità immagine nel browser del telefono, carica la foto dalla galleria e trascina il cursore a destra con il dito. Usa un preset rapido per un valore esatto, controlla la vista di confronto e scarica il risultato."},{"question":"Quale valore di luminosità devo usare per una foto scura in interni?","answer":"Parti da +15%, che è il valore di anteprima dello strumento, e aumenta a passi del 5% finché il soggetto è chiaramente visibile. Quasi tutte le foto in interni hanno bisogno del 15-30%. Fermati prima che le zone chiare, come finestre o lampade, diventino bianche."},{"question":"Posso scurire una foto troppo chiara?","answer":"Sì. Trascina il cursore a sinistra, verso valori negativi, come −15% o −30%. Scurire approfondisce le ombre e ripristina la ricchezza di una foto sovraesposta. Controlla le ombre, così non diventano macchie nere senza dettagli."},{"question":"Perché la mia foto schiarita mostra un rumore granuloso?","answer":"Schiarire fa emergere il rumore che era nascosto nelle ombre, e la compressione JPEG lo peggiora. Abbassa il cursore e accetta una foto leggermente più scura, oppure parti da un originale migliore, scattato con una buona luce. Uno schiarimento delicato mostra molto meno rumore di uno forte."},{"question":"Devo regolare la luminosità prima o dopo il contrasto?","answer":"Prima la luminosità, poi il contrasto. Schiarire alza il livello generale, e il contrasto ripristina la profondità che lo schiarimento può togliere. Farle in questo ordine rende ogni regolazione più facile da giudicare nella vista di confronto."},{"question":"Posso annullare una modifica di luminosità dopo aver scaricato?","answer":"Non dal file scaricato, perché la modifica è fissata nell’esportazione. Conserva la foto originale, così puoi provare un altro livello di luminosità. Nello strumento, usa l’opzione di reset per tornare a zero prima di scaricare."}];
